import elkRaw from "@/data/elk-harvest.json";
import deerRaw from "@/data/deer-harvest.json";

// Hunter success from WGFD's annual harvest reports, by hunt area and license
// type. Generated by scripts/hunts/build_harvest_data.py. The season is the
// one before the draw the pages show: the 2026 draw sits beside the 2025
// season's harvest. Server-only, like lib/elk.ts.

export interface HarvestStats {
  hunters: number; // active licenses (type rows) or active hunters (summary rows)
  harvest: number;
  days: number;
  success: number; // percent of active hunters who took an animal
  daysPerHarvest: number | null; // null when nobody took one
}

export interface AreaHarvest {
  name: string;
  types: Record<string, HarvestStats>; // "1", "GEN", "Other"
  total: HarvestStats;
  resident?: HarvestStats;
  nonresident?: HarvestStats;
}

interface Table {
  areas: Record<string, AreaHarvest>;
  regions: Record<string, HarvestStats>; // nonresident general licenses only
}

const elk = elkRaw as unknown as { season: number; source: string; reports: string; elk: Table };
const deer = deerRaw as unknown as { season: number; source: string; reports: string; mule: Table; whitetail: Table };

export const HARVEST_SEASON = elk.season;
export const ELK_HARVEST_SOURCE = elk.source;
export const DEER_HARVEST_SOURCE = deer.source;
export const HARVEST_REPORTS = elk.reports;

// Below this many hunters a success rate says little; pages mark it.
export const FEW_HUNTERS = 20;

export const elkAreaHarvest = (area: number) => elk.elk.areas[String(area)];
export const elkRegionHarvest = (region: string) => elk.elk.regions[region];

export type DeerKind = "mule" | "whitetail";
export const DEER_KINDS: { kind: DeerKind; label: string }[] = [
  { kind: "mule", label: "Mule deer" },
  { kind: "whitetail", label: "White-tailed deer" },
];

// Both tables for one area; an area missing from one had no hunters for that deer.
export function deerAreaHarvest(area: number): Partial<Record<DeerKind, AreaHarvest>> {
  return { mule: deer.mule.areas[String(area)], whitetail: deer.whitetail.areas[String(area)] };
}

export function deerRegionHarvest(region: string): Partial<Record<DeerKind, HarvestStats>> {
  return { mule: deer.mule.regions[region], whitetail: deer.whitetail.regions[region] };
}

// The success a license's hunters had, small enough for client components.
// Deer licenses carry the deer most of their hunters went after.
export interface LicenseHarvest {
  success: number;
  daysPerHarvest: number | null;
  hunters: number;
  of?: string; // "mule deer", "white-tailed deer"
}

const slim = (s: HarvestStats, of?: string): LicenseHarvest => ({
  success: s.success,
  daysPerHarvest: s.daysPerHarvest,
  hunters: s.hunters,
  ...(of ? { of } : {}),
});

export const elkLicenseHarvest = (s?: HarvestStats) => (s ? slim(s) : undefined);

export function deerLicenseHarvest(by: Partial<Record<DeerKind, HarvestStats>>): LicenseHarvest | undefined {
  const main = DEER_KINDS.map((k) => ({ ...k, s: by[k.kind] }))
    .filter((x): x is typeof x & { s: HarvestStats } => !!x.s && x.s.hunters > 0)
    .sort((a, b) => b.s.hunters - a.s.hunters)[0];
  return main && slim(main.s, main.label.toLowerCase());
}

const pct = (n: number) => `${Math.round(n)}%`;

// "58% of 169 hunters took an elk, about 18 days of hunting per animal".
export function successSentence(s: HarvestStats, animal: string): string {
  if (s.hunters === 0) return `Nobody hunted it in ${HARVEST_SEASON}.`;
  const days = s.daysPerHarvest === null ? "" : `, about ${Math.round(s.daysPerHarvest)} days of hunting per animal`;
  return `${pct(s.success)} of ${s.hunters.toLocaleString("en-US")} hunters took ${animal} in ${HARVEST_SEASON}${days}.`;
}

export const successShort = (h?: { success: number } | null) => (h ? pct(h.success) : "—");
